  let subject = config.subject || (isOverdue
    ? `⚠️ ${isTask ? 'TASK OVERDUE' : isInstall ? 'INSTALL DATE PASSED' : 'OVERDUE'}: ${isTask ? taskCtx.text : work_order.title}`
