          </div>
          <div style="padding: 20px;">
            <p><strong>${dateLabel}:</strong> ${safeDue}</p>
            <p><strong>Current Stage:</strong> ${safeStage}</p>
            <p><strong>Assigned To:</strong> ${safeAssigned}</p>
          </div>
        </div>
      `;
    } else {
      body = `
