import {createScanReporter,silentScanReporter} from '../../shared/permittingScanReporter.mjs';
import { withEntityRateLimitRetry } from '../../shared/entityRateLimitRetry.ts';
import { validatePermitDocumentBytes } from '../../shared/permittingDocumentValidation.mjs';
import { createClientFromRequest } from 'npm:@base44/sdk@0.8.23';
import { patchJurisdictionDocuments } from '../../shared/jurisdictionPersistence.mjs';
import { safeExternalFetch } from '../../shared/safeExternalFetch.ts';

const MAX_PERMIT_DOCUMENT_BYTES = 50 * 1024 * 1024;

async function permitDocumentSha256(bytes: Uint8Array) {
  const digest = await globalThis.crypto.subtle.digest('SHA-256', bytes);
  return Array.from(new Uint8Array(digest), byte => byte.toString(16).padStart(2, '0')).join('');
}

// Maps content-type to file extension
function getExtFromContentType(contentType, fallbackUrl) {
  if (!contentType) contentType = '';
  const ct = contentType.toLowerCase().split(';')[0].trim();
  const map = {
    'application/pdf': 'pdf',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document': 'docx',
    'application/msword': 'doc',
    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': 'xlsx',
    'application/vnd.ms-excel': 'xls',
    'text/plain': 'txt',
    'text/csv': 'csv',
    'text/html': 'html',
    'application/octet-stream': null, // fall through to URL
  };
  if (map[ct]) return map[ct];
  // Try to get from URL
  if (fallbackUrl) {
    const urlExt = fallbackUrl.split('?')[0].split('.').pop()?.toLowerCase();
    if (urlExt && urlExt.length <= 5) return urlExt;
  }
  return 'pdf'; // final fallback
}

async function readResponseBytes(response: Response) {
  const declaredLength = Number(response.headers.get('content-length') || 0);
  if (Number.isFinite(declaredLength) && declaredLength > MAX_PERMIT_DOCUMENT_BYTES) {
    throw Object.assign(new Error('Permit document exceeds the 50 MB safety limit.'), { status: 413 });
  }

  if (!response.body) {
    const bytes = new Uint8Array(await response.arrayBuffer());
    if (bytes.byteLength > MAX_PERMIT_DOCUMENT_BYTES) {
      throw Object.assign(new Error('Permit document exceeds the 50 MB safety limit.'), { status: 413 });
    }
    return bytes;
  }

  const reader = response.body.getReader();
  const chunks: Uint8Array[] = [];
  let total = 0;
  while (true) {
    const { value, done } = await reader.read();
    if (done) break;
    if (!value) continue;
    total += value.byteLength;
    if (total > MAX_PERMIT_DOCUMENT_BYTES) {
      await reader.cancel().catch(() => {});
      throw Object.assign(new Error('Permit document exceeds the 50 MB safety limit.'), { status: 413 });
    }
    chunks.push(value);
  }

  const bytes = new Uint8Array(total);
  let offset = 0;
  for (const chunk of chunks) {
    bytes.set(chunk, offset);
    offset += chunk.byteLength;
  }
  return bytes;
}

Deno.serve(async (req) => {
  let reporter:any=silentScanReporter;
  async function respond(data:any,options:any={}){return Response.json({...data,scan_run:await reporter.finish(data.error?'failed':'complete',data.error || '')},options);}
  try {
    const base44 = withEntityRateLimitRetry(createClientFromRequest(req));
    const user = await base44.auth.me().catch(() => null);

    if (!user) {
      return respond({ error: 'Unauthorized' }, { status: 401 });
    }

    const { jurisdiction_id, document_url, document_title,action_token } = await req.json();

    if (!jurisdiction_id || !document_url) {
      return respond({ error: 'Missing jurisdiction_id or document_url' }, { status: 400 });
    }

    // Re-read the live document before downloading. A source that has already
    // been archived and fingerprinted must match that exact archive before it can
    // be copied into live File Storage.
    const jurisdiction = await base44.entities.JurisdictionProfile.get(jurisdiction_id);
    if(action_token && user.role==='admin')reporter=await createScanReporter({entity:base44.asServiceRole.entities.PermittingScanRun,token:action_token,user,targetId:jurisdiction_id,targetName:jurisdiction.name,kind:'document',label:`Download ${document_title || document_url}`});
    const sourceDocument = (jurisdiction?.documents || []).find(doc => doc.url === document_url);
    if (!sourceDocument) {
      return respond({ error: 'Document source is no longer present on this jurisdiction' }, { status: 409 });
    }
    const expectedSha256 = String(sourceDocument.source_sha256 || '').trim().toLowerCase();
    const expectedBytes = Number(sourceDocument.source_bytes || 0);
    // Live storage ingest is only allowed for a fully archived/fingerprinted source.
    // This prevents an unpinned link (or a partially populated fingerprint) from
    // being silently treated as a collected document.
    if (!expectedSha256 || !Number.isSafeInteger(expectedBytes) || expectedBytes <= 0) {
      return respond({ error: 'Document has not been fully archived and fingerprinted; live ingest was blocked' }, { status: 409 });
    }
    if (!/^[a-f0-9]{64}$/.test(expectedSha256)) {
      return respond({ error: 'Stored source SHA-256 is invalid; live ingest was blocked' }, { status: 409 });
    }

    // Make retries idempotent at the backend boundary, not just in the UI. A
    // timeout after UploadFile can otherwise tempt an operator to retry and create
    // duplicate File Storage objects. Only treat an existing file as complete when
    // its stored proof exactly matches the archived source fingerprint.
    if (sourceDocument.file_url) {
      const storedSha256 = String(sourceDocument.stored_sha256 || '').trim().toLowerCase();
      const storedBytes = Number(sourceDocument.stored_bytes || 0);
      if (storedSha256 === expectedSha256 && storedBytes === expectedBytes) {
        return respond({
          success: true,
          already_stored: true,
          file_url: sourceDocument.file_url,
          jurisdiction,
        });
      }
      return respond({
        error: 'Document already has a File Storage URL without matching stored fingerprint proof; live ingest was blocked',
      }, { status: 409 });
    }

    // Download the file with browser-like headers
    const headers = {
      'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
      'Accept': '*/*'
    };

    await reporter.emit({kind:'download',url:document_url,detail:'Downloading original for comparison with its saved fingerprint.'},{stage:'Downloading original',current_url:document_url,processed:0,total:3,indeterminate:false});
    let fileResponse;
    try {
      fileResponse = await safeExternalFetch(document_url, { headers });
    } catch (fetchErr) {
      if (Number(fetchErr?.status || 0) === 400) throw fetchErr;
      fileResponse = await safeExternalFetch(document_url);
    }

    if (!fileResponse.ok) {
      return respond({ error: `Failed to download file (HTTP ${fileResponse.status})` }, { status: 400 });
    }

    const contentType = fileResponse.headers.get('content-type') || '';
    const ext = getExtFromContentType(contentType, document_url);

    // A removed form may redirect to an HTTP 200 HTML error page. Never store it
    // as a downloaded permit document or report the source file as complete.
    if (/\b(?:text\/html|application\/xhtml\+xml)\b/i.test(contentType)) {
      return respond({ error: 'Source returned a web page instead of a downloadable document' }, { status: 415 });
    }
    const fileBytes = await readResponseBytes(fileResponse);
    if (fileBytes.byteLength === 0) {
      return respond({ error: 'Downloaded file is empty' }, { status: 400 });
    }
    validatePermitDocumentBytes(fileBytes, {format: ext, contentType});

    if (expectedBytes > 0 && fileBytes.byteLength !== expectedBytes) {
      return respond({ error: `Official source changed size since archival (${fileBytes.byteLength} bytes received; ${expectedBytes} expected). Re-verify before live ingest.` }, { status: 409 });
    }
    const sourceSha256 = await permitDocumentSha256(fileBytes);
    if (expectedSha256 && sourceSha256 !== expectedSha256) {
      return respond({ error: 'Official source SHA-256 changed since archival. Re-verify before live ingest.' }, { status: 409 });
    }

    const safeTitle = (document_title || 'document').replace(/[^a-zA-Z0-9_\- ]/g, '_');
    const fileName = `${safeTitle}.${ext}`;
    const mimeType = contentType.split(';')[0].trim() || 'application/octet-stream';
    const file = new File([fileBytes], fileName, { type: mimeType });

    // Upload to app's file system
    await reporter.emit({kind:'upload',detail:`Validated ${fileBytes.byteLength} source bytes; uploading file.`},{stage:'Uploading file',processed:1,total:3});
    const uploadResult = await base44.integrations.Core.UploadFile({ file });

    if (!uploadResult?.file_url) {
      return respond({ error: 'Failed to upload file' }, { status: 500 });
    }

    // Patch only the matching document against the latest Jurisdiction snapshot so
    // concurrent document additions/edits are preserved instead of replacing the array.
    await reporter.emit({kind:'saving',detail:'Saving file URL and fingerprint against the current document identity.'},{stage:'Saving document receipt',processed:2,total:3});
    const downloadedAt = new Date().toISOString();
    const updatedJurisdiction = await patchJurisdictionDocuments({
      entity: base44.entities.JurisdictionProfile,
      jurisdictionId: jurisdiction_id,
      documentUrl: document_url,
      patch: {
        file_url: uploadResult.file_url,
        downloaded_at: downloadedAt,
        stored_sha256: sourceSha256,
        stored_bytes: fileBytes.byteLength,
      },
      label: `Jurisdiction document download ${document_title || document_url}`,
    });

    return respond({ 
      success: true, 
      file_url: uploadResult.file_url,
      jurisdiction: updatedJurisdiction,
    });
  } catch (error) {
    const status = Number(error?.status || 500);
    const safeStatus = [400, 401, 409, 413, 415, 429].includes(status) ? status : 500;
    console.error('downloadPermitPDF error:', error?.message || error);
    return respond({
      error: safeStatus === 500 ? 'Permit document could not be downloaded safely' : error.message,
    }, { status: safeStatus });
  }
});

import { createClientFromRequest } from 'npm:@base44/sdk@0.8.52';
import { withEntityRateLimitRetry } from '../../shared/entityRateLimitRetry.ts';
import {
  COMMAND_SPECS, canTransition, isTerminal, commandAllowed, routeAgent,
  resolveRole, normalizeFileBridgeSettings, normPath, pathKey, parentPath,
  baseName, extOf, kindOf, safeRelPath, dedupeKey, isExcluded,
  FB_SSE_HOLD_MS, FB_HEALTHY_AGE_MS, FB_REPLAY_WINDOW_MS,
} from '../../shared/fileBridgeModel.ts';

// fileBridgeIngest — HMAC-authenticated agent API (outbound-only transport).
// Agent holds NO Base44 credentials: it signs {key_id, ts, body} with a shared
// secret delivered via env (FILEBRIDGE_HMAC_KEY / _PREV for rotation).

const enc = new TextEncoder();
const te = new TextDecoder();

const toHex = (b: ArrayBuffer | Uint8Array) =>
  [...new Uint8Array(b as ArrayBuffer)].map((x) => x.toString(16).padStart(2, '0')).join('');

const hmac = async (key: string, msg: string): Promise<string> => {
  const k = await crypto.subtle.importKey('raw', enc.encode(key), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  return toHex(await crypto.subtle.sign('HMAC', k, enc.encode(msg)));
};

const timingSafeEq = (a: string, b: string): boolean => {
  if (a.length !== b.length) return false;
  let d = 0;
  for (let i = 0; i < a.length; i += 1) d |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return d === 0;
};

const uuid = () => crypto.randomUUID();
const now = () => Date.now();

const sha256Hex = async (bytes: Uint8Array): Promise<string> =>
  toHex(await crypto.subtle.digest('SHA-256', bytes.slice().buffer));

async function verifyAgent(req: Request, rawBody: string, sr: any) {
  const keyId = req.headers.get('x-fb-key-id') || '';
  const ts = Number(req.headers.get('x-fb-ts') || '0');
  const sig = req.headers.get('x-fb-sig') || '';
  const agentId = req.headers.get('x-fb-agent') || '';
  if (!keyId || !ts || !sig) return { ok: false, status: 401, error: 'missing auth headers' };
  if (Math.abs(now() - ts) > FB_REPLAY_WINDOW_MS) return { ok: false, status: 401, error: 'stale timestamp' };
  const gs = await getSettings(sr);
  if (gs.error === 'stale_on_error') { /* served last-good — fine */ }
  else if (gs.error) return { ok: false, status: 503, error: 'settings_unavailable' };
  const settings = normalizeFileBridgeSettings(gs.v);
  if (keyId !== String(settings.key_id || 'fbk1')) return { ok: false, status: 401, error: 'bad key_id' };
  const cur = Deno.env.get('FILEBRIDGE_HMAC_KEY') || '';
  const prev = Deno.env.get('FILEBRIDGE_HMAC_KEY_PREV') || '';
  if (!cur) return { ok: false, status: 503, error: 'bridge key not configured' };
  const expectedCur = await hmac(cur, `${ts}.${rawBody}`);
  const expectedPrev = prev ? await hmac(prev, `${ts}.${rawBody}`) : '';
  const ok = timingSafeEq(sig, expectedCur) || (prev ? timingSafeEq(sig, expectedPrev) : false);
  if (!ok) return { ok: false, status: 401, error: 'bad signature' };
  return { ok: true, agentId, settings };
}

let settingsCache: { v: any; at: number } = { v: null, at: 0 };
let lastGood: { v: any; at: number } = { v: null, at: 0 };
// Reads can fail under the shared entity budget — NEVER translate a read
// failure into 'disabled'. Serve last-good settings for ≤10min on error.
async function getSettings(sr: any): Promise<{ v: any; error?: string }> {
  if (settingsCache.v && now() - settingsCache.at < 60_000) return { v: settingsCache.v };
  const rows = await sr.entities.GlobalSettings.filter({ setting_key: 'fileBridge' }, '-updated_date', 1)
    .catch((e: any) => ({ __err: String(e?.message || e) }));
  if (rows?.__err) {
    if (lastGood.v && now() - lastGood.at < 600_000) return { v: lastGood.v, error: 'stale_on_error' };
    return { v: null, error: rows.__err };
  }
  const v = rows?.[0]?.setting_value ?? null;
  settingsCache = { v, at: now() };
  if (v) lastGood = { v, at: now() };
  return { v };
}

const ev = (sr: any, e: Record<string, any>) =>
  sr.entities.FileBridgeEvent.create({ ts: now(), severity: 'info', ...e }).catch(() => null);

async function getHealth(sr: any, agentId: string) {
  const rows = await sr.entities.FileBridgeHealth.filter({ agent_id: agentId }, '-updated_date', 1).catch(() => []);
  return rows?.[0] || null;
}

async function upsertHealth(sr: any, agentId: string, patch: Record<string, any>) {
  const row = await getHealth(sr, agentId);
  // index_stats is the free-object field — merge rather than replace so
  // handshake-written keys (e.g. detected_shares) survive heartbeat stats.
  const merged = { ...patch };
  if (patch.index_stats && row?.index_stats) merged.index_stats = { ...row.index_stats, ...patch.index_stats };
  if (row) return sr.entities.FileBridgeHealth.update(row.id, { ...merged, last_seen_ms: now() });
  return sr.entities.FileBridgeHealth.create({ agent_id: agentId, last_seen_ms: now(), state: 'online', ...merged });
}

async function pendingCommands(sr: any, agentId: string, limit = 10) {
  const rows = await sr.entities.FileBridgeCommand.filter(
    { agent_id: agentId, status: 'queued' }, 'created_ts', limit * 3,
  ).catch((e: any) => ({ __err: String(e?.message || e) }));
  if (rows?.__err || !Array.isArray(rows)) return rows;
  // Base44 sort is single-field only — order by priority in memory.
  rows.sort((a: any, b: any) => (b.priority || 0) - (a.priority || 0) || a.created_ts - b.created_ts);
  return rows.slice(0, limit);
}

const BUNDLE_REV = 'fb-ingest-2026-11-05a';

// Assemble staged FileBridgeChunk rows for a command → UploadFile → stamp
// FileIndex.delivered_url → purge chunks → complete command. Shared by
// deliver_chunk (last-arriving seq) and deliver_stitch (explicit retry after
// a partial stage, e.g. a worker died mid-assembly). Caller must ensure cmd
// is not terminal.
async function stitchStaged(sr: any, cmd: any, ordered: any[], agentId: string, opts: { file_sha256?: string; name?: string }) {
  const parts: Uint8Array[] = [];
  for (const c of ordered) {
    const resp = await fetch(String(c.file_url));
    if (!resp.ok) return { ok: false as const, status: 503, body: { error: `chunk fetch ${c.seq} failed`, retry: true } };
    parts.push(new Uint8Array(await resp.arrayBuffer()));
  }
  const size = parts.reduce((n, p) => n + p.length, 0);
  if (size > 256 * 1024 * 1024) return { ok: false as const, status: 413, body: { error: 'assembled over 256MB cap', needs_proxy: true } };
  const whole = new Uint8Array(size);
  let off = 0; for (const p of parts) { whole.set(p, off); off += p.length; }
  const wholeSha = await sha256Hex(whole);
  if (opts.file_sha256 && opts.file_sha256 !== wholeSha) {
    await sr.entities.FileBridgeChunk.deleteMany({ id: { $in: ordered.map((c: any) => c.id).filter(Boolean) } }).catch(() => null);
    return { ok: false as const, status: 409, body: { error: 'assembled sha256 mismatch — chunks purged, re-deliver', retry: true } };
  }
  const file = new File([whole], String(opts.name || 'delivery.bin'));
  const up = await sr.integrations.Core.UploadFile({ file });
  if (cmd.args?.root_key && cmd.args?.path) {
    const pk = pathKey(cmd.agent_id || agentId, cmd.args.root_key, cmd.args.path);
    const ir = await sr.entities.FileIndex.filter({ path_key: pk }, '-updated_date', 1).catch(() => []);
    if (ir?.[0]) {
      await sr.entities.FileIndex.update(ir[0].id, {
        delivered_url: up.file_url, delivered_at_ms: now(), sha256: wholeSha,
      }).catch(() => null);
    }
  }
  await sr.entities.FileBridgeChunk.deleteMany({ id: { $in: ordered.map((c: any) => c.id).filter(Boolean) } }).catch(() => null);
  if (!isTerminal(cmd.status)) {
    await sr.entities.FileBridgeCommand.update(cmd.id, {
      status: 'completed', updated_ts: now(),
      result: { file_url: up.file_url, bytes: size, sha256: wholeSha },
    });
  }
  return { ok: true as const, status: 200, body: { ok: true, file_url: up.file_url, bytes: size, sha256: wholeSha, assembled: true } };
}

Deno.serve(async (req) => {
  const rawBody = await req.text();
  const client = withEntityRateLimitRetry(createClientFromRequest(req), { maxRetries: 3 });
  const sr = (client as any).asServiceRole;
  let body: any = {};
  try { body = rawBody ? JSON.parse(rawBody) : {}; } catch { return Response.json({ error: 'bad json' }, { status: 400 }); }

  const auth = await verifyAgent(req, rawBody, sr);
  if (!auth.ok) {
    await ev(sr, { event_type: 'auth_failed', actor: req.headers.get('x-fb-agent') || 'unknown', severity: 'warn', details: { reason: auth.error } });
    return Response.json({ error: auth.error }, { status: auth.status });
  }
  const settings = auth.settings;
  const action = String(body.action || '');
  const agentId = auth.agentId || String(body.agent_id || '');

  // ---------- bootstrap_settings: first-run setup (HMAC-gated). Creates the
  // settings row if absent so the bridge can come up without manual UI steps.
  if (action === 'bootstrap_settings') {
    const rows = await sr.entities.GlobalSettings.filter({ setting_key: 'fileBridge' }, '-updated_date', 1).catch(() => []);
    const raw = rows?.[0]?.setting_value;
    const exists = !!(raw && typeof raw === 'object' && Object.keys(raw).length);
    const next = normalizeFileBridgeSettings({
      ...(exists ? raw : {}),
      enabled: true, primary_agent_id: agentId, key_id: String(body.key_id || 'fbk1'),
      ...(body.settings && typeof body.settings === 'object' ? body.settings : {}),
    });
    let writeErr = '';
    if (exists) {
      const u = await sr.entities.GlobalSettings.update(rows[0].id, { setting_value: next }).catch((e: any) => ({ __err: String(e?.message || e) }));
      if (u?.__err) writeErr = u.__err;
    } else {
      const c = await sr.entities.GlobalSettings.create({ setting_key: 'fileBridge', setting_value: next }).catch((e: any) => ({ __err: String(e?.message || e) }));
      if (c?.__err) writeErr = c.__err;
    }
    settingsCache = { v: null, at: 0 };
    await ev(sr, { event_type: 'bootstrap_settings', agent_id: agentId, actor: agentId, details: { existed: exists, writeErr } });
    return Response.json({ ok: !writeErr, existed: exists, settings: next, ...(writeErr ? { error: `settings write failed: ${writeErr}` } : {}) }, { status: writeErr ? 503 : 200 });
  }

  if (!settings.enabled) return Response.json({ error: 'fileBridge disabled', rev: BUNDLE_REV }, { status: 503 });

  // ---------- handshake ----------
  if (action === 'handshake') {
    const envRole = String(body.env_role || '');
    const role = resolveRole(agentId, envRole, settings);
    // singleton-primary guard: never two live primaries
    if (role === 'primary') {
      const rows = await sr.entities.FileBridgeHealth.filter({ role: 'primary' }, '-updated_date', 5).catch(() => []);
      const other = (rows || []).find((r: any) => r.agent_id !== agentId && now() - (r.last_seen_ms || 0) < FB_HEALTHY_AGE_MS);
      if (other) {
        await ev(sr, { event_type: 'role_conflict', agent_id: agentId, actor: agentId, severity: 'error', details: { existing: other.agent_id } });
        return Response.json({ error: `primary already held by ${other.agent_id}`, role: 'observer' }, { status: 409 });
      }
    }
    await upsertHealth(sr, agentId, {
      role, state: 'online', agent_version: body.agent_version || '', agent_host: body.host || '',
      display_name: body.display_name || agentId, spool_depth: body.spool_depth || 0,
      index_stats: { detected_shares: body.detected_shares || null },
    });
    const roots = await sr.entities.FileShareRoot.filter({ agent_id: agentId }, 'root_key', 50).catch(() => []);
    return Response.json({
      ok: true, agent_id: agentId, role,
      config_version: settings.config_version,
      config: {
        roots: roots || [], exclude_patterns: settings.exclude_patterns,
        extraction_roots: settings.extraction_roots, content_search: settings.content_search,
      },
      detect_roots: body.detected_shares || null,
      server_time_ms: now(),
    });
  }

  // ---------- heartbeat ----------
  if (action === 'heartbeat') {
    await upsertHealth(sr, agentId, {
      state: 'online', spool_depth: body.spool_depth || 0,
      index_stats: body.index_stats || undefined, last_scan_at: body.last_scan_at || undefined,
      error: body.error || '',
    });
    return Response.json({ ok: true, config_version: settings.config_version, server_time_ms: now(), rev: BUNDLE_REV });
  }

  // ---------- command_poll (short-poll fallback) ----------
  if (action === 'command_poll') {
    await upsertHealth(sr, agentId, { state: 'online' });
    const cmds = await pendingCommands(sr, agentId);
    if ((cmds as any)?.__err) return Response.json({ error: 'read_unavailable', retry: true }, { status: 503 });
    // lease them
    const leased: any[] = [];
    for (const c of cmds as any[]) {
      const spec = COMMAND_SPECS[c.type];
      const lease_ms = spec?.lease_ms || 60_000;
      const u = await sr.entities.FileBridgeCommand.update(c.id, {
        status: 'leased', leased_by: agentId, lease_expires_ms: now() + lease_ms, updated_ts: now(),
      }).catch(() => null);
      if (u) leased.push({ command_id: c.command_id, id: c.id, type: c.type, args: c.args });
    }
    return Response.json({ ok: true, commands: leased, server_time_ms: now(), rev: BUNDLE_REV });
  }

  // ---------- command_wait (SSE long-poll = primary wake channel) ----------
  if (action === 'command_wait') {
    await upsertHealth(sr, agentId, { state: 'online' });
    const holdMs = Math.min(Number(body.hold_ms) || FB_SSE_HOLD_MS, 55_000);
    const stream = new ReadableStream({
      async start(controller) {
        const send = (o: any) => {
          try { controller.enqueue(enc.encode(`data: ${JSON.stringify(o)}\n\n`)); } catch { /* closed */ }
        };
        send({ type: 'hello', agent_id: agentId, server_time_ms: now() });
        const t0 = now();
        while (now() - t0 < holdMs) {
          const cmds = await pendingCommands(sr, agentId, 5);
          if ((cmds as any)?.__err) { send({ type: 'degraded' }); await new Promise((r) => setTimeout(r, 4000)); continue; }
          if ((cmds as any[]).length) {
            for (const c of cmds as any[]) {
              const spec = COMMAND_SPECS[c.type];
              const u = await sr.entities.FileBridgeCommand.update(c.id, {
                status: 'leased', leased_by: agentId,
                lease_expires_ms: now() + (spec?.lease_ms || 60_000), updated_ts: now(),
              }).catch(() => null);
              if (u) send({ type: 'command', command_id: c.command_id, id: c.id, cmd_type: c.type, args: c.args });
            }
          }
          await new Promise((r) => setTimeout(r, 800));
          send({ type: 'tick', t: now() - t0 });
        }
        send({ type: 'bye', held_ms: now() - t0 });
        controller.close();
      },
    });
    return new Response(stream, {
      headers: { 'content-type': 'text/event-stream', 'cache-control': 'no-cache', 'x-accel-buffering': 'no' },
    });
  }

  // ---------- command_complete (idempotent) ----------
  if (action === 'command_complete') {
    const cid = String(body.command_id || '');
    const rows = await sr.entities.FileBridgeCommand.filter({ command_id: cid }, '-updated_date', 1)
      .catch((e: any) => ({ __err: String(e?.message || e) }));
    if ((rows as any)?.__err) return Response.json({ error: 'read_unavailable', retry: true }, { status: 503 });
    const cmd = rows?.[0];
    if (!cmd) return Response.json({ error: 'unknown command' }, { status: 404 });
    if (isTerminal(cmd.status)) return Response.json({ ok: true, already: true }); // idempotent
    const to = body.success === false ? 'failed' : 'completed';
    if (!canTransition(cmd.status, to)) {
      return Response.json({ error: `bad transition ${cmd.status}->${to}` }, { status: 409 });
    }
    await sr.entities.FileBridgeCommand.update(cmd.id, {
      status: to, result: body.result || {}, error: body.error || '',
      progress: body.progress || undefined, updated_ts: now(),
    });
    // upload_apply completion stamps the permanent provenance ledger.
    if (cmd.type === 'upload_apply' && cmd.args?.upload_id) {
      await sr.entities.FileBridgeUpload.update(cmd.args.upload_row || '', {
        status: to === 'completed' ? 'applied' : 'failed',
        applied_at: to === 'completed' ? new Date().toISOString() : undefined,
        error: to === 'completed' ? '' : String(body.error || 'apply failed').slice(0, 300),
        path: body.result?.path || undefined,
      }).catch(async () => {
        const rows = await sr.entities.FileBridgeUpload.filter({ upload_id: cmd.args.upload_id }, '-updated_date', 1).catch(() => []);
        if (rows?.[0]) {
          await sr.entities.FileBridgeUpload.update(rows[0].id, {
            status: to === 'completed' ? 'applied' : 'failed',
            applied_at: to === 'completed' ? new Date().toISOString() : undefined,
            error: to === 'completed' ? '' : String(body.error || 'apply failed').slice(0, 300),
            path: body.result?.path || undefined,
          }).catch(() => null);
        }
      });
    }
    return Response.json({ ok: true });
  }

  // ---------- command_progress ----------
  if (action === 'command_progress') {
    const rows = await sr.entities.FileBridgeCommand.filter({ command_id: String(body.command_id || '') }, '-updated_date', 1).catch(() => []);
    const cmd = rows?.[0];
    if (!cmd || isTerminal(cmd.status)) return Response.json({ ok: true });
    await sr.entities.FileBridgeCommand.update(cmd.id, { progress: body.progress || {}, status: 'running', updated_ts: now() }).catch(() => null);
    return Response.json({ ok: true });
  }

  // ---------- index_batch (entity-id-first; bulkCreate inserts; one batched resolve) ----------
  if (action === 'index_batch') {
    const items: any[] = Array.isArray(body.items) ? body.items.slice(0, 500) : [];
    const t0 = now();
    const toUpdate: Array<{ id: string; data: any }> = [];
    const toResolve: any[] = [];
    const idMap: Record<string, string> = {};
    for (const it of items) {
      const rp = safeRelPath(String(it.path || ''));
      if (!rp.ok) continue;
      const data: any = {
        agent_id: agentId, root_key: String(it.root_key || ''),
        path: rp.path, name: baseName(rp.path), parent_path: parentPath(rp.path),
        ext: extOf(rp.path), kind: kindOf(rp.path),
        served_by: body.served_by || undefined,
        last_seen_scan: body.scan_id || undefined,
      };
      // State fields apply ONLY when present — scan items carry them, but
      // sparse patches (pin/relink) must not wipe existing values.
      if (it.is_dir !== undefined) data.is_dir = !!it.is_dir;
      if (it.size !== undefined) data.size = it.size || 0;
      if (it.mtime_ms !== undefined) data.mtime_ms = it.mtime_ms || 0;
      if (it.dir_size_bytes !== undefined) data.dir_size_bytes = it.dir_size_bytes;
      if (it.missing !== undefined) data.missing = !!it.missing;
      if (it.customer_ids !== undefined) data.customer_ids = it.customer_ids;
      if (it.hot !== undefined) data.hot = !!it.hot;
      if (it.hot_score !== undefined) data.hot_score = it.hot_score;
      if (it.pinned !== undefined) data.pinned = !!it.pinned;
      if (it.entity_id) toUpdate.push({ id: String(it.entity_id), data });
      else toResolve.push(data);
    }
    // one batched path_key resolution for unknowns
    if (toResolve.length) {
      const keys = toResolve.map((d) => pathKey(d.agent_id, d.root_key, d.path));
      // A swallowed read error here would turn known rows into duplicate
      // path_key creates — surface it, the agent retries the whole batch.
      const found = await sr.entities.FileIndex.filter({ path_key: { $in: keys.slice(0, 200) } }, undefined, 500)
        .catch((e: any) => ({ __err: String(e?.message || e) }));
      if ((found as any)?.__err) return Response.json({ error: 'read_unavailable', retry: true }, { status: 503 });
      const byKey = new Map(((found as any[]) || []).map((r: any) => [r.path_key, r.id]));
      const toCreate: any[] = [];
      toResolve.forEach((d, i) => {
        const pk = keys[i];
        const existing = byKey.get(pk);
        if (existing) { toUpdate.push({ id: existing, data: d }); idMap[pk] = existing; }
        else toCreate.push({
          ...d, path_key: pk, creation_request_key: pk,
          origin: 'external', managed_by: 'none',
          customer_ids: d.customer_ids || [], pinned: !!d.pinned,
          hot: !!d.hot, hot_score: d.hot_score || 0,
        });
      });
      if (toCreate.length) {
        const created = await sr.entities.FileIndex.bulkCreate(toCreate)
          .catch((e: any) => ({ __err: String(e?.message || e) }));
        if ((created as any)?.__err) return Response.json({ error: 'write_unavailable', retry: true }, { status: 503 });
        for (const r of (created as any[]) || []) if (r?.path_key) idMap[r.path_key] = r.id;
      }
    }
    let updateFailures = 0;
    for (const u of toUpdate) {
      const r = await sr.entities.FileIndex.update(u.id, u.data).catch(() => null);
      if (!r) updateFailures += 1;
    }
    return Response.json({
      ok: true, received: items.length, updated: toUpdate.length - updateFailures,
      update_failures: updateFailures || undefined,
      id_map: idMap, suggested_batch_size: items.length >= 500 ? 500 : Math.max(100, items.length * 2),
      elapsed_ms: now() - t0,
    });
  }

  // ---------- thumb_push / preview_push ----------
  if (action === 'thumb_push' || action === 'preview_push') {
    const pk = String(body.path_key || '');
    const rows = await sr.entities.FileIndex.filter({ path_key: pk }, '-updated_date', 1)
      .catch((e: any) => ({ __err: String(e?.message || e) }));
    if ((rows as any)?.__err) return Response.json({ error: 'read_unavailable', retry: true }, { status: 503 });
    const row = rows?.[0];
    if (!row) return Response.json({ error: 'no index row' }, { status: 404 });
    const bytes = Uint8Array.from(atob(String(body.bytes_b64 || '')), (c) => c.charCodeAt(0));
    if (bytes.length > 2 * 1024 * 1024) return Response.json({ error: 'rendition too large' }, { status: 413 });
    const file = new File([bytes], action === 'thumb_push' ? 'thumb.webp' : 'preview.pdf');
    const up = await sr.integrations.Core.UploadFile({ file });
    const patch: any = action === 'thumb_push'
      ? { thumb_url: up.file_url }
      : { preview_url: up.file_url, preview_state: 'ready' };
    await sr.entities.FileIndex.update(row.id, patch);
    return Response.json({ ok: true, file_url: up.file_url });
  }

  // ---------- deliver_complete (≤48MB single-shot full bytes) ----------
  if (action === 'deliver_complete') {
    const cid = String(body.command_id || '');
    const rows = await sr.entities.FileBridgeCommand.filter({ command_id: cid }, '-updated_date', 1)
      .catch((e: any) => ({ __err: String(e?.message || e) }));
    if ((rows as any)?.__err) return Response.json({ error: 'read_unavailable', retry: true }, { status: 503 });
    const cmd = rows?.[0];
    if (!cmd) return Response.json({ error: 'unknown command' }, { status: 404 });
    const bytes = Uint8Array.from(atob(String(body.bytes_b64 || '')), (c) => c.charCodeAt(0));
    if (bytes.length > 48 * 1024 * 1024) return Response.json({ error: 'over inline cap' }, { status: 413 });
    const file = new File([bytes], String(body.name || 'delivery.bin'));
    const up = await sr.integrations.Core.UploadFile({ file });
    // stamp delivered_url on the index row when identifiable
    if (cmd.args?.root_key && cmd.args?.path) {
      const pk = pathKey(cmd.agent_id || agentId, cmd.args.root_key, cmd.args.path);
      const ir = await sr.entities.FileIndex.filter({ path_key: pk }, '-updated_date', 1).catch(() => []);
      if (ir?.[0]) {
        await sr.entities.FileIndex.update(ir[0].id, {
          delivered_url: up.file_url, delivered_at_ms: now(), sha256: body.sha256 || undefined,
        }).catch(() => null);
      }
    }
    if (!isTerminal(cmd.status)) {
      await sr.entities.FileBridgeCommand.update(cmd.id, {
        status: 'completed', updated_ts: now(),
        result: { file_url: up.file_url, bytes: bytes.length, sha256: body.sha256 || '' },
      });
    }
    return Response.json({ ok: true, file_url: up.file_url });
  }

  // ---------- deliver_chunk (>48MB staged delivery) ----------
  // Agent posts raw chunks; each is UploadFile'd and staged in FileBridgeChunk.
  // When all `total` seqs are present, chunks are fetched back, assembled,
  // whole-file sha256 verified, uploaded, and the command completed.
  // Re-posting a seq is idempotent (dedupe on command_id+seq).
  if (action === 'deliver_chunk') {
    const cid = String(body.command_id || '');
    const seq = Number(body.seq);
    const total = Number(body.total);
    if (!cid || !Number.isInteger(seq) || !Number.isInteger(total) || seq < 0 || total < 1 || seq >= total || total > 64) {
      return Response.json({ error: 'bad chunk envelope' }, { status: 400 });
    }
    const cmdRows = await sr.entities.FileBridgeCommand.filter({ command_id: cid }, '-updated_date', 1)
      .catch((e: any) => ({ __err: String(e?.message || e) }));
    if ((cmdRows as any)?.__err) return Response.json({ error: 'read_unavailable', retry: true }, { status: 503 });
    const cmd = cmdRows?.[0];
    if (!cmd) return Response.json({ error: 'unknown command' }, { status: 404 });
    if (isTerminal(cmd.status)) return Response.json({ ok: true, already: true, file_url: cmd.result?.file_url });

    const bytes = Uint8Array.from(atob(String(body.bytes_b64 || '')), (c) => c.charCodeAt(0));
    if (bytes.length > 48 * 1024 * 1024) return Response.json({ error: 'chunk over inline cap' }, { status: 413 });

    // stage this seq (dedupe)
    const have = await sr.entities.FileBridgeChunk.filter({ command_id: cid }, 'seq', 64).catch(() => []);
    if (!(have || []).some((c: any) => c.seq === seq)) {
      const csha = String(body.sha256 || '') || await sha256Hex(bytes);
      const file = new File([bytes], `${cid}.part${seq}`);
      const up = await sr.integrations.Core.UploadFile({ file });
      const created = await sr.entities.FileBridgeChunk.create({
        command_id: cid, seq, file_url: up.file_url, bytes: bytes.length, sha256: csha, received_at: now(),
      }).catch(() => null);
      have.push({ id: created?.id, seq, file_url: up.file_url, bytes: bytes.length, sha256: csha });
    }
    const received = (have || []).length;
    if (!isTerminal(cmd.status)) {
      await sr.entities.FileBridgeCommand.update(cmd.id, {
        progress: { done: received, total, label: 'receiving' }, updated_ts: now(),
      }).catch(() => null);
    }
    if (received < total) return Response.json({ ok: true, received, total });

    // ---- assemble ----
    const ordered = (have || []).slice().sort((a: any, b: any) => a.seq - b.seq);
    const st = await stitchStaged(sr, cmd, ordered, agentId, { file_sha256: body.file_sha256, name: body.name });
    return Response.json(st.body, { status: st.status });
  }

  // ---------- deliver_stitch (explicit re-assembly — no new bytes) ----------
  // Recovery path for a command whose chunks all staged but assembly never ran
  // (worker died between last chunk and assemble). Idempotent: re-checks the
  // staged set against `total` (body or cmd.progress.total) and stitches.
  if (action === 'deliver_stitch') {
    const cid = String(body.command_id || '');
    if (!cid) return Response.json({ error: 'bad command_id' }, { status: 400 });
    const cmdRows = await sr.entities.FileBridgeCommand.filter({ command_id: cid }, '-updated_date', 1)
      .catch((e: any) => ({ __err: String(e?.message || e) }));
    if ((cmdRows as any)?.__err) return Response.json({ error: 'read_unavailable', retry: true }, { status: 503 });
    const cmd = cmdRows?.[0];
    if (!cmd) return Response.json({ error: 'unknown command' }, { status: 404 });
    if (isTerminal(cmd.status)) return Response.json({ ok: true, already: true, file_url: cmd.result?.file_url });
    const total = Number(body.total) || Number(cmd.progress?.total) || 0;
    const have = await sr.entities.FileBridgeChunk.filter({ command_id: cid }, 'seq', 64)
      .catch((e: any) => ({ __err: String(e?.message || e) }));
    if ((have as any)?.__err) return Response.json({ error: 'read_unavailable', retry: true }, { status: 503 });
    const staged = (have || []) as any[];
    if (!total || staged.length < total) {
      return Response.json({ ok: true, assembled: false, received: staged.length, total }, { status: 200 });
    }
    const seqs = new Set(staged.map((c: any) => c.seq));
    for (let i = 0; i < total; i++) {
      if (!seqs.has(i)) return Response.json({ ok: true, assembled: false, missing_seq: i, received: staged.length, total });
    }
    const ordered = staged.slice().sort((a: any, b: any) => a.seq - b.seq);
    const st = await stitchStaged(sr, cmd, ordered, agentId, { file_sha256: body.file_sha256, name: body.name });
    return Response.json(st.body, { status: st.status });
  }

  // ---------- event ----------
  if (action === 'event') {
    await ev(sr, {
      event_type: String(body.event_type || 'agent_event'), agent_id: agentId, actor: agentId,
      severity: ['info', 'warn', 'error'].includes(body.severity) ? body.severity : 'info',
      root_key: body.root_key, path: body.path ? normPath(body.path) : undefined,
      command_id: body.command_id, customer_id: body.customer_id, details: body.details || {},
    });
    return Response.json({ ok: true });
  }

  // ---------- recent_batch ----------
  if (action === 'recent_batch') {
    const items: any[] = Array.isArray(body.items) ? body.items.slice(0, 300) : [];
    const rows = items.map((it) => {
      const rp = safeRelPath(String(it.path || ''));
      return rp.ok ? {
        agent_id: agentId, root_key: String(it.root_key || ''), path: rp.path,
        name: baseName(rp.path), ext: extOf(rp.path), is_dir: !!it.is_dir,
        change_type: ['created', 'modified', 'deleted', 'moved'].includes(it.change_type) ? it.change_type : 'modified',
        size: it.size || 0, mtime_ms: it.mtime_ms || 0,
        customer_id: it.customer_id || undefined, event_ts: it.event_ts || now(), seq: it.seq || now(),
      } : null;
    }).filter(Boolean);
    if (rows.length) await sr.entities.FileBridgeRecent.bulkCreate(rows).catch(() => null);
    return Response.json({ ok: true, received: rows.length });
  }

  // ---------- manifest_export (ledger → agent manifest rebuild source) ----------
  // The FileBridgeUpload append-only ledger is the durable provenance record —
  // it survives index reaping and agent reinstalls, so a promoted/reinstalled
  // agent can rebuild manifest.json (the delete/move security boundary) from it.
  if (action === 'manifest_export') {
    const rows = await sr.entities.FileBridgeUpload.filter(
      { agent_id: agentId }, 'created_date', 2000,
    ).catch((e: any) => ({ __err: String(e?.message || e) }));
    if ((rows as any)?.__err) return Response.json({ error: 'read_unavailable', retry: true }, { status: 503 });
    const entries = (rows || []).filter((u: any) => u.status !== 'failed').map((u: any) => ({
      root_key: u.root_key, path: u.path, origin: 'bridge', managed_by: 'bridge',
      upload_id: u.upload_id, uploaded_by: u.uploaded_by, created_ts: u.created_ts || 0,
    }));
    return Response.json({ ok: true, entries });
  }

  // ---------- manifest_sync (drift check: agent manifest vs server ledger) ----------
  // Agent sends a digest of its local manifest.json; server digests the
  // FileBridgeUpload ledger the same way and reports in_sync. Canonical form:
  // sorted 'root_key|path|origin|managed_by' lines, sha256 hex.
  if (action === 'manifest_sync') {
    const rows = await sr.entities.FileBridgeUpload.filter(
      { agent_id: agentId }, 'created_date', 2000,
    ).catch((e: any) => ({ __err: String(e?.message || e) }));
    if ((rows as any)?.__err) return Response.json({ error: 'read_unavailable', retry: true }, { status: 503 });
    const lines = (rows || []).filter((u: any) => u.status !== 'failed')
      .map((u: any) => `${u.root_key}|${u.path}|bridge|bridge`).sort();
    const serverDigest = await sha256Hex(new TextEncoder().encode(lines.join('\n')));
    const agentDigest = String(body.digest || '');
    const agentCount = Number(body.count) || 0;
    return Response.json({
      ok: true,
      in_sync: agentDigest === serverDigest && agentCount === lines.length,
      server_digest: serverDigest, server_count: lines.length,
      drift: agentDigest === serverDigest ? lines.length - agentCount : null,
    });
  }

  // ---------- inventory_report (per-ext openability + totals snapshot) ----------
  if (action === 'inventory_report') {
    const runId = String(body.run_id || `inv-${agentId}-${now()}`);
    const status = ['running', 'completed', 'failed', 'paused'].includes(body.status) ? body.status : 'completed';
    const existing = await sr.entities.FileBridgeInventory.filter(
      { run_id: runId, agent_id: agentId }, '-updated_date', 1,
    ).catch((e: any) => ({ __err: String(e?.message || e) }));
    if ((existing as any)?.__err) return Response.json({ error: 'read_unavailable', retry: true }, { status: 503 });
    const row = {
      run_id: runId, agent_id: agentId, status,
      roots: Array.isArray(body.roots) ? body.roots.map(String).slice(0, 50) : [],
      totals: body.totals && typeof body.totals === 'object' ? body.totals : {},
      ext_map: body.ext_map && typeof body.ext_map === 'object' ? body.ext_map : {},
      top_dirs: Array.isArray(body.top_dirs) ? body.top_dirs.slice(0, 100) : [],
      cursor: body.cursor && typeof body.cursor === 'object' ? body.cursor : {},
      errors: Array.isArray(body.errors) ? body.errors.slice(0, 50) : [],
      ...(body.started_at ? { started_at: String(body.started_at) } : {}),
      ...(status === 'completed' || status === 'failed' ? { finished_at: new Date(now()).toISOString() } : {}),
    };
    if (existing?.[0]) {
      await sr.entities.FileBridgeInventory.update(existing[0].id, row).catch(() => null);
      return Response.json({ ok: true, run_id: runId, updated: true });
    }
    const c = await sr.entities.FileBridgeInventory.create(row).catch((e: any) => ({ __err: String(e?.message || e) }));
    if ((c as any)?.__err) return Response.json({ error: 'write_unavailable', retry: true }, { status: 503 });
    return Response.json({ ok: true, run_id: runId });
  }

  // ---------- become_primary (failover promotion — mutating) ----------
  // Backup agent asks to take primary. Allowed when: no primary configured,
  // this agent already is primary, the configured primary is stale/offline,
  // or `force:true`. Updates settings + health role; emits a failover event.
  if (action === 'become_primary') {
    const current = String(settings.primary_agent_id || '');
    if (current === agentId) {
      return Response.json({ ok: true, role: 'primary', already: true });
    }
    if (current && !body.force) {
      const rows = await sr.entities.FileBridgeHealth.filter({ agent_id: current }, '-updated_date', 1)
        .catch((e: any) => ({ __err: String(e?.message || e) }));
      if ((rows as any)?.__err) return Response.json({ error: 'read_unavailable', retry: true }, { status: 503 });
      const cur = rows?.[0];
      const fresh = cur && now() - (cur.last_seen_ms || 0) < FB_HEALTHY_AGE_MS;
      if (fresh) {
        await ev(sr, { event_type: 'failover_refused', agent_id: agentId, actor: agentId, severity: 'warn', details: { primary: current, primary_state: cur.state } });
        return Response.json({ error: `primary '${current}' still healthy`, primary: current, primary_last_seen_ms: cur.last_seen_ms }, { status: 409 });
      }
    }
    // promote: settings row update (find it first — bootstrap guarantees it exists)
    const gs = await sr.entities.GlobalSettings.filter({ setting_key: 'fileBridge' }, '-updated_date', 1)
      .catch((e: any) => ({ __err: String(e?.message || e) }));
    if ((gs as any)?.__err) return Response.json({ error: 'read_unavailable', retry: true }, { status: 503 });
    if (!gs?.[0]) return Response.json({ error: 'settings row missing — run bootstrap_settings' }, { status: 503 });
    const nextSettings = normalizeFileBridgeSettings({ ...settings, primary_agent_id: agentId });
    const u = await sr.entities.GlobalSettings.update(gs[0].id, { setting_value: nextSettings })
      .catch((e: any) => ({ __err: String(e?.message || e) }));
    if (u?.__err) return Response.json({ error: 'write_unavailable', retry: true }, { status: 503 });
    settingsCache = { v: null, at: 0 };
    await upsertHealth(sr, agentId, { role: 'primary', state: 'online' });
    if (current) await upsertHealth(sr, current, { role: 'backup', state: 'demoted' }).catch(() => null);
    await ev(sr, { event_type: 'failover_promoted', agent_id: agentId, actor: agentId, severity: 'warn', details: { previous_primary: current || null, forced: !!body.force } });
    const roots = await sr.entities.FileShareRoot.filter({ agent_id: agentId }, 'root_key', 50).catch(() => []);
    return Response.json({
      ok: true, role: 'primary', previous_primary: current || null,
      config_version: nextSettings.config_version,
      config: { roots: roots || [], exclude_patterns: nextSettings.exclude_patterns },
    });
  }

  return Response.json({ error: `unknown action '${action}'` }, { status: 400 });
});

import { createClientFromRequest } from 'npm:@base44/sdk@0.8.52';
import {
  FB_HEALTHY_AGE_MS, FB_RECENT_RING_CAP, MATCH_AUTO, matchCustomerFolders,
  normalizeFileBridgeSettings,
} from '../../shared/fileBridgeModel.ts';
import { withEntityRateLimitRetry } from '../../shared/entityRateLimitRetry.ts';

// fileBridgeMaintenance — scheduled hands-off sweeps (workflow: every 5 min).
// 1. Expire queued commands past expires_at_ms; requeue stale leases once.
// 2. Mark agent health stale/offline from last_seen_ms.
// 3. TTL-sweep FileBridgeEvent (90d), FileBridgeRecent (ring cap), FileBridgeChunk (1h),
//    FileBridgeCommand (24h terminal).
// 4. delivered_url dereference sweep — keep newest within keep_delivered_max_mb
//    (no storage delete API; deref only). Files re-deliver on next open.
// 5. link_match — auto-match top-level customer_folders dirs to Customers.
// 6. link_reconcile — heal broken links + re-derive FileIndex.customer_ids.

const now = () => Date.now();
const DAY = 86_400_000;

Deno.serve(async (req) => {
  const base44 = withEntityRateLimitRetry(createClientFromRequest(req), { paceMs: 200 });
  const sr = (base44 as any).asServiceRole;
  const out: any = { at: new Date().toISOString(), sweeps: {} };

  const settingsRow = await sr.entities.GlobalSettings.filter({ setting_key: 'fileBridge' }, '-updated_date', 1).catch(() => []);
  const settings = normalizeFileBridgeSettings(settingsRow?.[0]?.setting_value);
  if (!settings.enabled) return Response.json({ skipped: 'disabled', ...out });

  // ---- command sweeps ----
  let expired = 0, requeued = 0;
  const staleQueued = await sr.entities.FileBridgeCommand.filter(
    { status: 'queued', expires_at_ms: { $lt: now() } }, 'created_ts', 100,
  ).catch(() => []);
  for (const c of staleQueued || []) {
    await sr.entities.FileBridgeCommand.update(c.id, { status: 'expired', updated_ts: now(), error: 'queue ttl' }).catch(() => null);
    expired += 1;
  }
  const staleLeases = await sr.entities.FileBridgeCommand.filter(
    { status: { $in: ['leased', 'running'] }, lease_expires_ms: { $lt: now() } }, 'created_ts', 100,
  ).catch(() => []);
  for (const c of staleLeases || []) {
    // one requeue attempt, then expire — protects against agent death mid-lease
    const retries = Number((c as any).args?._lease_retries || 0);
    if (retries < 1) {
      await sr.entities.FileBridgeCommand.update(c.id, {
        status: 'queued', leased_by: '', lease_expires_ms: 0, updated_ts: now(),
        args: { ...(c.args || {}), _lease_retries: retries + 1 },
      }).catch(() => null);
      requeued += 1;
    } else {
      await sr.entities.FileBridgeCommand.update(c.id, { status: 'expired', updated_ts: now(), error: 'lease lost' }).catch(() => null);
      expired += 1;
    }
  }
  out.sweeps.commands = { expired, requeued };

  // ---- health staleness ----
  let marked = 0;
  const agents = await sr.entities.FileBridgeHealth.filter({ state: 'online' }, '-updated_date', 20).catch(() => []);
  for (const a of agents || []) {
    const age = now() - (a.last_seen_ms || 0);
    const to = age > FB_HEALTHY_AGE_MS * 4 ? 'offline' : age > FB_HEALTHY_AGE_MS ? 'stale' : '';
    if (to) {
      await sr.entities.FileBridgeHealth.update(a.id, { state: to }).catch(() => null);
      marked += 1;
    }
  }
  out.sweeps.health = { marked };

  // ---- TTL sweeps ----
  const cutoff90 = now() - 90 * DAY;
  const oldEvents = await sr.entities.FileBridgeEvent.filter({ ts: { $lt: cutoff90 } }, 'ts', 200).catch(() => []);
  if (oldEvents?.length) {
    await sr.entities.FileBridgeEvent.deleteMany({ id: { $in: oldEvents.map((r: any) => r.id) } }).catch(() => null);
  }
  const recentRows = await sr.entities.FileBridgeRecent.filter({}, '-event_ts', FB_RECENT_RING_CAP + 500).catch(() => []);
  let recentDeleted = 0;
  if ((recentRows || []).length > FB_RECENT_RING_CAP) {
    const excess = recentRows.slice(FB_RECENT_RING_CAP).map((r: any) => r.id);
    await sr.entities.FileBridgeRecent.deleteMany({ id: { $in: excess } }).catch(() => null);
    recentDeleted = excess.length;
  }
  const oldChunks = await sr.entities.FileBridgeChunk.filter({ received_at: { $lt: now() - 3_600_000 } }, 'received_at', 200).catch(() => []);
  if (oldChunks?.length) {
    await sr.entities.FileBridgeChunk.deleteMany({ id: { $in: oldChunks.map((r: any) => r.id) } }).catch(() => null);
  }
  // completed commands older than 24h — keep results visible but bounded
  const oldCmds = await sr.entities.FileBridgeCommand.filter(
    { status: { $in: ['completed', 'failed', 'expired', 'cancelled'] }, updated_ts: { $lt: now() - DAY } },
    'updated_ts', 200,
  ).catch(() => []);
  if (oldCmds?.length) {
    await sr.entities.FileBridgeCommand.deleteMany({ id: { $in: oldCmds.map((r: any) => r.id) } }).catch(() => null);
  }
  out.sweeps.retention = {
    events_deleted: oldEvents?.length || 0, recent_deleted: recentDeleted,
    chunks_deleted: oldChunks?.length || 0, commands_deleted: oldCmds?.length || 0,
  };

  // ---- delivered_url dereference sweep ----
  // UploadFile has no delete API — delivered blobs accumulate. Keep the newest
  // deliveries within keep_delivered_max_mb; deref the rest (file re-delivers
  // on next open — the blob stays orphaned but the index stops pointing at it).
  const capBytes = (settings.keep_delivered_max_mb || 4096) * 1024 * 1024;
  const delivered = await sr.entities.FileIndex.filter(
    { delivered_at_ms: { $gt: 0 } }, '-delivered_at_ms', 500,
  ).catch(() => []);
  let derefed = 0, keptBytes = 0;
  for (const row of delivered || []) {
    keptBytes += Number(row.size || 0);
    if (keptBytes > capBytes) {
      await sr.entities.FileIndex.update(row.id, { delivered_url: '', delivered_at_ms: 0 }).catch(() => null);
      derefed += 1;
    }
  }
  out.sweeps.delivered = { rows: delivered?.length || 0, kept_mb: Math.round(keptBytes / 1048576), derefed };

  // ---- customer folder link matching ----
  // Top-level dirs on purpose:'customer_folders' roots vs Customer.company_name.
  // >=MATCH_AUTO unambiguous -> confirmed+auto; otherwise suggested for human review.
  // Existing link on a folder (any status, incl rejected_sticky) -> never re-suggest.
  const linkStats: any = { candidates: 0, created: 0, auto_confirmed: 0, skipped_existing: 0, errors: 0 };
  const custRoots = await sr.entities.FileShareRoot.filter(
    { purpose: 'customer_folders', enabled: true }, 'root_key', 20,
  ).catch(() => []);
  const customers = await sr.entities.Customer.filter({}, 'company_name', 2000)
    .catch((e: any) => ({ __err: String(e?.message || e) }));
  const cList = Array.isArray(customers)
    ? customers.map((c: any) => ({ id: c.id, name: c.company_name || c.name || '' })).filter((c: any) => c.name)
    : null;
  if (custRoots?.length && cList?.length) {
    for (const root of custRoots) {
      const dirs = await sr.entities.FileIndex.filter(
        { root_key: root.root_key, is_dir: true, parent_path: '', missing: { $ne: true } },
        'name', 500,
      ).catch(() => []);
      if (!dirs?.length) continue;
      const existing = await sr.entities.CustomerFolderLink.filter(
        { root_key: root.root_key }, 'folder_path', 1000,
      ).catch(() => []);
      const taken = new Set((existing || []).map((l: any) => l.folder_path));
      const byPath = new Map(dirs.map((d: any) => [d.path, d]));
      const matches = matchCustomerFolders(dirs.map((d: any) => d.path), cList);
      linkStats.candidates += matches.length;
      for (const m of matches) {
        const dir = byPath.get(m.folder);
        if (!dir || taken.has(m.folder)) { linkStats.skipped_existing += 1; continue; }
        const auto = m.confidence >= MATCH_AUTO;
        const c = await sr.entities.CustomerFolderLink.create({
          creation_request_key: `link|${dir.agent_id || root.agent_id || ''}|${root.root_key}|${m.folder}|${m.customer_id}`,
          customer_id: m.customer_id, customer_name: m.customer_name,
          agent_id: dir.agent_id || root.agent_id || '', root_key: root.root_key,
          folder_path: m.folder, confidence: m.confidence, signals: m.signals,
          status: auto ? 'confirmed' : 'suggested', auto,
        }).catch((e: any) => ({ __err: String(e?.message || e) }));
        if (c?.__err) linkStats.errors += 1;
        else { linkStats.created += 1; if (auto) linkStats.auto_confirmed += 1; taken.add(m.folder); }
      }
    }
  }
  out.sweeps.link_match = linkStats;

  // ---- link reconcile (FB-31) ----
  // a) broken-link detection: linked folder missing/renamed → status:'broken'
  //    (folder reappears → restores previous status). Renamed folders surface
  //    as NEW suggestions via the match sweep above.
  // b) customer_ids[] re-derivation: rows under a confirmed link's folder get
  //    customer_id added — powers customer-scoped search_hot + panel scoping.
  //    Additive only (never strips; wrong-strip is worse than stale-add).
  //    Capped at 100 updates/run to protect the shared entity budget.
  const recStats: any = { checked: 0, broken: 0, healed: 0, cid_updates: 0 };
  const allLinks = await sr.entities.CustomerFolderLink.filter(
    { status: { $in: ['confirmed', 'suggested', 'broken'] } }, 'folder_path', 500,
  ).catch(() => []);
  const escRx = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  // Broken-link check, batched: one $in filter per root_key (chunks of 100
  // paths) instead of a per-link point read — was ~1 read per link. On a
  // batch error we fall back to per-link reads rather than trusting an
  // empty result (a silent miss would mass-mark links broken).
  const linksByRoot = new Map<string, any[]>();
  for (const l of allLinks || []) {
    const arr = linksByRoot.get(l.root_key) || [];
    arr.push(l);
    linksByRoot.set(l.root_key, arr);
  }
  const aliveLinks = new Set<string>();
  const perLinkCheck = async (l: any): Promise<boolean> => {
    const dir = await sr.entities.FileIndex.filter(
      { root_key: l.root_key, path: l.folder_path, is_dir: true }, '-updated_date', 1,
    ).catch(() => []);
    return !!dir?.[0] && !dir[0].missing;
  };
  for (const [rootKey, links] of linksByRoot) {
    const paths = [...new Set(links.map((l: any) => l.folder_path))];
    const found = new Set<string>();
    let batched = true;
    for (let i = 0; i < paths.length; i += 100) {
      const rows: any = await sr.entities.FileIndex.filter(
        { root_key: rootKey, is_dir: true, path: { $in: paths.slice(i, i + 100) } },
        '-updated_date', 500,
      ).catch((e: any) => ({ __err: String(e?.message || e) }));
      if (rows?.__err || !Array.isArray(rows)) { batched = false; break; }
      for (const r of rows) if (!r.missing) found.add(r.path);
    }
    if (batched) {
      for (const l of links) if (found.has(l.folder_path)) aliveLinks.add(l.id);
    } else {
      for (const l of links) if (await perLinkCheck(l)) aliveLinks.add(l.id);
    }
  }
  for (const l of allLinks || []) {
    recStats.checked += 1;
    const alive = aliveLinks.has(l.id);
    if (!alive && l.status !== 'broken') {
      await sr.entities.CustomerFolderLink.update(l.id, {
        status: 'broken', broken_at: now(), prev_status: l.status,
      }).catch(() => null);
      recStats.broken += 1;
    } else if (alive && l.status === 'broken') {
      await sr.entities.CustomerFolderLink.update(l.id, {
        status: l.prev_status || 'suggested', broken_at: 0, prev_status: '',
      }).catch(() => null);
      recStats.healed += 1;
    }
  }
  let cidBudget = 100;
  // customer_ids re-derivation, batched: one alternation-regex filter per
  // root_key per 15-folder chunk instead of a per-link filter — was ~1 read
  // per confirmed link. Updates are collected first, so a row under several
  // confirmed folders still receives every customer id in a single write.
  const confByRoot = new Map<string, any[]>();
  for (const l of (allLinks || []).filter((x: any) => x.status === 'confirmed')) {
    const arr = confByRoot.get(l.root_key) || [];
    arr.push(l);
    confByRoot.set(l.root_key, arr);
  }
  const pendingCids = new Map<string, Set<string>>();
  for (const [rootKey, links] of confByRoot) {
    const folders = [...new Set(links.map((l: any) => l.folder_path))];
    const linkByFolder = new Map(links.map((l: any) => [l.folder_path, l]));
    for (let i = 0; i < folders.length; i += 15) {
      const chunk = folders.slice(i, i + 15);
      const rx = `^(${chunk.map(escRx).join('|')})(/|$)`;
      const rows = await sr.entities.FileIndex.filter(
        { root_key: rootKey, missing: { $ne: true }, path: { $regex: rx } },
        'path', 2500,
      ).catch(() => []);
      for (const f of rows || []) {
        for (const folder of chunk) {
          if (f.path !== folder && !f.path.startsWith(folder + '/')) continue;
          const l = linkByFolder.get(folder);
          if (!l || (f.customer_ids || []).includes(l.customer_id)) continue;
          const pending = pendingCids.get(f.id) || new Set(f.customer_ids || []);
          pending.add(l.customer_id);
          pendingCids.set(f.id, pending);
        }
      }
    }
  }
  for (const [rowId, ids] of pendingCids) {
    if (cidBudget <= 0) break;
    const u = await sr.entities.FileIndex.update(rowId, { customer_ids: [...ids] }).catch(() => null);
    if (u !== null) { recStats.cid_updates += 1; cidBudget -= 1; }
  }
  out.sweeps.link_reconcile = recStats;

  await sr.entities.FileBridgeEvent.create({
    event_type: 'maintenance_run', actor: 'system', severity: 'info', ts: now(), details: out.sweeps,
  }).catch(() => null);

  return Response.json(out);
});

import { createClientFromRequest } from 'npm:@base44/sdk@0.8.52';

// FB-02 probe — THROWAWAY function. Measures platform limits for the Unraid
// File Bridge design. Delete before publish.
const PROBE_KEY = 'fbspike-7f3a2c91e4b8d6a0c5f2e9b1a4d7c8e3';

const b64ToBytes = (s: string) => Uint8Array.from(atob(s || ''), (c) => c.charCodeAt(0));

Deno.serve(async (req) => {
  try {
    const body = await req.json().catch(() => ({}));
    if (body?.probe_key !== PROBE_KEY) {
      return Response.json({ error: 'no' }, { status: 403 });
    }
    const client = createClientFromRequest(req);
    const sr = (client as any).asServiceRole;
    const out: any = { probe: body.probe, at: new Date().toISOString() };

    if (body.probe === 'body_size') {
      const raw = String(body.bytes_b64 || '');
      out.received_b64_len = raw.length;
      out.approx_bytes = Math.floor(raw.length * 0.75);
      return Response.json(out);
    }

    if (body.probe === 'entity_write_speed') {
      const n = Math.min(Number(body.count) || 10, 100);
      const E = sr.entities.FileBridgeSpikeRow;
      const t0 = Date.now();
      const ids: string[] = [];
      for (let i = 0; i < n; i += 1) {
        const row = await E.create({ seq: i, probe_run: String(body.run || 'x') });
        ids.push(row.id);
      }
      out.serial_ms_per_write = (Date.now() - t0) / n;
      out.count = n;
      out.cleaned = (await E.deleteMany({ id: { $in: ids } }).catch((e: any) => ({ err: String(e?.message || e) }))) as any;
      return Response.json(out);
    }

    if (body.probe === 'bulk_api') {
      const E: any = sr.entities.FileBridgeSpikeRow;
      out.methods = {};
      for (const name of ['bulkCreate', 'createMany', 'insertMany', 'bulkInsert']) {
        out.methods[name] = typeof E[name] === 'function' ? 'present' : 'absent';
      }
      // try whichever exists
      const fn = ['bulkCreate', 'createMany'].find((m) => typeof E[m] === 'function');
      if (fn) {
        try {
          const rows = Array.from({ length: 5 }, (_, i) => ({ seq: 900 + i, probe_run: 'bulk' }));
          const res = await E[fn](rows);
          out.bulk_result_type = Array.isArray(res) ? `array:${res.length}` : typeof res;
          const ids = (Array.isArray(res) ? res : res?.records || res?.ids || []).map((r: any) => r?.id || r).filter(Boolean);
          if (ids.length) await E.deleteMany({ id: { $in: ids } }).catch(() => null);
          out.bulk_created = ids.length;
        } catch (e: any) {
          out.bulk_error = String(e?.message || e).slice(0, 300);
        }
      }
      return Response.json(out);
    }

    if (body.probe === 'upload') {
      const bytes = b64ToBytes(String(body.bytes_b64 || ''));
      const file = new File([bytes], String(body.name || 'fb-spike.bin'), { type: 'application/octet-stream' });
      try {
        const up = await sr.integrations.Core.UploadFile({ file });
        out.upload = up;
      } catch (e: any) {
        out.upload_error = String(e?.message || e).slice(0, 400);
      }
      // probe delete APIs on integrations.Core surface
      const core: any = sr.integrations.Core;
      out.core_keys = Object.getOwnPropertyNames(Object.getPrototypeOf(core) || core).slice(0, 50);
      out.integration_keys = Object.keys(sr.integrations || {});
      if (out.upload?.file_url) {
        for (const name of ['DeleteFile', 'deleteFile', 'RemoveFile', 'Delete']) {
          if (typeof core[name] === 'function') {
            try {
              const r = await core[name]({ file_url: out.upload.file_url });
              out[`delete_${name}`] = { ok: true, result: r };
            } catch (e: any) {
              out[`delete_${name}`] = { ok: false, error: String(e?.message || e).slice(0, 300) };
            }
          } else {
            out[`delete_${name}`] = 'absent';
          }
        }
      }
      return Response.json(out);
    }

    if (body.probe === 'sse') {
      const holdMs = Math.min(Number(body.hold_ms) || 10000, 120000);
      const encoder = new TextEncoder();
      const stream = new ReadableStream({
        async start(controller) {
          const t0 = Date.now();
          controller.enqueue(encoder.encode(`data: {"probe":"sse","t":0}\n\n`));
          while (Date.now() - t0 < holdMs) {
            await new Promise((r) => setTimeout(r, 2000));
            try {
              controller.enqueue(encoder.encode(`data: {"t":${Date.now() - t0}}\n\n`));
            } catch {
              return;
            }
          }
          controller.enqueue(encoder.encode(`data: {"done":true,"held_ms":${holdMs}}\n\n`));
          controller.close();
        },
      });
      return new Response(stream, {
        headers: {
          'content-type': 'text/event-stream',
          'cache-control': 'no-cache',
          'x-accel-buffering': 'no',
        },
      });
    }

    if (body.probe === 'actor_wake') {
      try {
        const actors: any = (client as any).actors;
        if (!actors) {
          out.actor_error = 'client.actors absent on request-scoped client';
          return Response.json(out);
        }
        out.actor_keys = Object.getOwnPropertyNames(actors).filter((k) => !k.startsWith('_')).slice(0, 40);
        const t0 = Date.now();
        const room = actors.fileBridgeSpike ? actors.fileBridgeSpike(String(body.room || 'spike-room')) : null;
        if (!room) {
          out.actor_error = 'actors.fileBridgeSpike accessor absent';
          return Response.json(out);
        }
        const conn = room.connect({ id: 'fn-probe-' + Date.now() });
        // give the socket a moment to open
        await new Promise((r) => setTimeout(r, 1200));
        conn.send({ type: 'wake', from: 'function', at: Date.now() });
        await new Promise((r) => setTimeout(r, 400));
        out.connect_ms = Date.now() - t0;
        out.sent = true;
        try { conn.close?.(); } catch { /* ignore */ }
      } catch (e: any) {
        out.actor_error = String(e?.message || e).slice(0, 400);
      }
      return Response.json(out);
    }

    if (body.probe === 'env') {
      out.runtime = { deno: typeof Deno !== 'undefined', now: Date.now() };
      out.env_keys = ['FILEBRIDGE_HMAC_KEY', 'FILEBRIDGE_HMAC_KEY_PREV']
        .filter((k) => !!Deno.env.get(k));
      return Response.json(out);
    }

    if (body.probe === 'set_fb_settings') {
      const rows = await sr.entities.GlobalSettings.filter({ setting_key: 'fileBridge' }, '-updated_date', 1).catch(() => []);
      const value = body.value && typeof body.value === 'object' ? body.value : { enabled: true };
      if (rows?.[0]?.id) {
        await sr.entities.GlobalSettings.update(rows[0].id, { setting_value: value });
        out.updated = true;
      } else {
        await sr.entities.GlobalSettings.create({ setting_key: 'fileBridge', setting_value: value });
        out.created = true;
      }
      out.setting_value = value;
      return Response.json(out);
    }

    if (body.probe === 'mk_cmd') {
      const row = await sr.entities.FileBridgeCommand.create({
        command_id: String(body.command_id || 'cmd_spike_' + Date.now()),
        type: String(body.cmd_type || 'log_tail'),
        agent_id: String(body.agent_id || 'dev-primary'),
        status: 'queued', args: body.args || { lines: 10 },
        dedupe_key: 'spike', request_key: 'spike',
        created_ts: Date.now(), updated_ts: Date.now(),
      });
      out.created_command = row?.id;
      return Response.json(out);
    }

    if (body.probe === 'list_cmds') {
      const rows = await sr.entities.FileBridgeCommand.filter(
        { agent_id: String(body.agent_id || 'dev-primary') }, '-created_ts', 10,
      ).catch((e: any) => ({ err: String(e?.message || e) }));
      out.commands = rows;
      return Response.json(out);
    }

    if (body.probe === 'gs_dump') {
      const gs = await sr.entities.GlobalSettings.filter({ setting_key: 'fileBridge' }, '-updated_date', 10)
        .catch((e: any) => ({ err: String(e?.message || e) }));
      const cmds = await sr.entities.FileBridgeCommand.filter(
        { agent_id: String(body.agent_id || 'dev-primary') }, '-created_ts', 10,
      ).catch((e: any) => ({ err: String(e?.message || e) }));
      out.settings_rows = gs;
      out.commands = Array.isArray(cmds) ? cmds.map((c) => ({ command_id: c.command_id, type: c.type, status: c.status, leased_by: c.leased_by })) : cmds;
      return Response.json(out);
    }

    return Response.json({ error: 'unknown probe', known: ['body_size', 'entity_write_speed', 'bulk_api', 'upload', 'sse', 'actor_wake', 'env', 'set_fb_settings', 'mk_cmd', 'list_cmds'] }, { status: 400 });
  } catch (error: any) {
    return Response.json({ error: String(error?.message || error).slice(0, 500) }, { status: 500 });
  }
});

import { createClientFromRequest } from 'npm:@base44/sdk@0.8.52';
import { withEntityRateLimitRetry } from '../../shared/entityRateLimitRetry.ts';
import { readSourceEvidencePages } from '../../shared/jurisdictionSourceTextSegments.mjs';

Deno.serve(async req => {
  try {
    const base44=withEntityRateLimitRetry(createClientFromRequest(req));
    const user=await base44.auth.me().catch(()=>null);
    if (!user || !['admin','user'].includes(user.role)) return Response.json({error:'Staff access required'},{status:403});
    const body=await req.json().catch(()=>({}));
    const id=String(body.source_document_id || '').trim();
    const startPage=body.start_page ?? 1, pageCount=body.page_count ?? 5;
    if (!id || !Number.isInteger(startPage) || startPage<1 || !Number.isInteger(pageCount) || pageCount<1 || pageCount>5)
      return Response.json({error:'Select a source and one to five physical PDF pages.'},{status:400});
    // Use caller RLS for both source and segment reads, not service-role access.
    const entity=base44.entities.PermittingSourceDocument;
    const source=await entity.get(id);
    const evidence=await readSourceEvidencePages({source,segmentEntity:base44.entities.PermittingSourceTextSegment,startPage,pageCount});
    const latest=await entity.get(id);
    const snapshot=row=>JSON.stringify([row.archived_file_url,row.file_hash_sha256,row.file_bytes,row.text_extraction_state,row.extracted_text,row.extracted_pages]);
    if (snapshot(latest)!==snapshot(source)) return Response.json({error:'Source evidence changed while reading; request the current snapshot.'},{status:409});
    return Response.json({success:true,source_document_id:id,source_sha256:source.file_hash_sha256,
      official_url:source.official_url,archived_file_url:source.archived_file_url,
      authority_classification:source.authority_classification,content_status:source.content_status,
      verification_status:source.verification_status,...evidence,llm_calls:0});
  } catch(error) {
    console.error('getPermittingSourceTextPages:',error?.message || error);
    return Response.json({error:'Page evidence is unavailable or requires review.'},{status:409});
  }
});

